-- 151: Original BrillaPrep WASSCE BrillaPrep transitional Electronics beta content blueprint questions, part 1.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_151_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_151_guard;
INSERT INTO _migration_151_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_001' AND NOT (q.topic_id IS 'topic_was_electronics_b002_1' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What should be done before changing components on an energised electronics bench circuit?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Disconnect the supply and discharge stored energy safely","B. Switch off the supply but leave charged capacitors untouched","C. Remove only the fuse while the circuit remains connected","D. Short capacitor terminals directly with an uninsulated tool"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Isolation and controlled capacitor discharge prevent electric shock, burns and accidental component damage from stored charge. Therefore the correct answer is A: Disconnect the supply and discharge stored energy safely.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_001' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_151_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_002' AND NOT (q.topic_id IS 'topic_was_electronics_b002_1' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How is a voltmeter connected when measuring the voltage across a resistor?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. In series with the resistor and load current","B. In parallel with the resistor","C. In parallel with the ammeter only","D. Across the supply without identifying the resistor terminals"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A voltmeter compares potential at two points and therefore connects in parallel while presenting high input resistance. Therefore the correct answer is B: In parallel with the resistor.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_002' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_151_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_003' AND NOT (q.topic_id IS 'topic_was_electronics_b002_1' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the purpose of a shunt resistor in an analogue ammeter?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Increase movement resistance by being connected in series","B. Protect the movement by opening on overload","C. Carry most of the measured current around the sensitive meter movement","D. Adjust the pointer to zero before current flows"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A low-value shunt shares current with the movement, extending current range while only the rated fraction flows through the coil. Therefore the correct answer is C: Carry most of the measured current around the sensitive meter movement.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_003' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_151_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_004' AND NOT (q.topic_id IS 'topic_was_electronics_b002_1' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does the time-base control of an oscilloscope set?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The vertical voltage represented per division","B. The trigger voltage that begins each sweep","C. The brightness of the displayed trace","D. The horizontal time represented per division"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The time base controls horizontal sweep rate, allowing period, frequency and timing relationships to be read from the graticule. Therefore the correct answer is D: The horizontal time represented per division.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_1' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_004' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_151_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_electronics_b002_005' AND NOT (q.topic_id IS 'topic_was_electronics_b002_1' AND q.subject_id IS 'subj_wassce_electronics' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is an oscilloscope probe ground lead connected only to an appropriate circuit reference?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. An incorrect ground connection can short a live point through protective earth","B. The probe input isolates its ground from protective earth","C. Any circuit point is safe because the lead has high resistance","D. The ground reference affects only trace position, not current flow"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Bench oscilloscope grounds are often earth-referenced, so careless connection can create a destructive high-current path and a shock hazard. Therefore the correct answer is A: An incorrect ground connection can short a live point through protective earth.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_electronics_b002_1' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_electronics_b002_005' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Electronics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_electronics_b002_001', 'topic_was_electronics_b002_1', 'subj_wassce_electronics', 'exam_wassce', NULL, NULL, 'What should be done before changing components on an energised electronics bench circuit?', 'multiple_choice', NULL, '["A. Disconnect the supply and discharge stored energy safely","B. Switch off the supply but leave charged capacitors untouched","C. Remove only the fuse while the circuit remains connected","D. Short capacitor terminals directly with an uninsulated tool"]', 'A', 'Isolation and controlled capacitor discharge prevent electric shock, burns and accidental component damage from stored charge. Therefore the correct answer is A: Disconnect the supply and discharge stored energy safely.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_electronics_b002_1', 'Identify', 'AO1', NULL, NULL, 'board_waec');
